def main(data: str, query: str) -> dict:
    import json

    def extract_object(raw):
        if isinstance(raw, dict):
            return raw
        if not isinstance(raw, str) or not raw.strip():
            raise ValueError("输入为空")
        text = raw.strip().lstrip("\ufeff")
        try:
            value = json.loads(text)
            if isinstance(value, dict):
                return value
        except Exception:
            pass

        if text.startswith("```"):
            lines = text.splitlines()
            if lines and lines[0].strip().startswith("```"):
                lines = lines[1:]
            if lines and lines[-1].strip() == "```":
                lines = lines[:-1]
            text = "\n".join(lines).strip()

        start = text.find("{")
        if start < 0:
            raise ValueError("未找到JSON对象")
        depth = 0
        in_string = False
        escaped = False
        for index in range(start, len(text)):
            char = text[index]
            if in_string:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == '"':
                    in_string = False
                continue
            if char == '"':
                in_string = True
            elif char == "{":
                depth += 1
            elif char == "}":
                depth -= 1
                if depth == 0:
                    value = json.loads(text[start:index + 1])
                    if not isinstance(value, dict):
                        raise TypeError("JSON根节点必须是Object")
                    return value
        raise ValueError("JSON对象括号不完整")

    errors = []
    for label, raw in (("data", data), ("query", query)):
        try:
            value = extract_object(raw)
            return {"parsed_data": value, "parse_ok": True, "parse_err": ""}
        except Exception as exc:
            errors.append(f"{label}：{exc}")
    return {
        "parsed_data": {},
        "parse_ok": False,
        "parse_err": "；".join(errors),
    }

def main(parsed_data: dict, parse_ok: bool, parse_err: str) -> dict:
    import json

    if not parse_ok:
        raise ValueError(f"业务JSON解析失败：{parse_err}")
    if not isinstance(parsed_data, dict) or not parsed_data:
        raise ValueError("业务JSON必须是非空Object")

    required = [
        "第1章_筛选条件及概况",
        "2.1_节前一天线路客运量",
        "2.2_假日期间线路客运量",
        "3.1_节前一天高峰断面",
        "3.2_假日期间高峰断面",
        "3.2.1_分时断面与空间分布",
        "4.1_重点车站预测客流",
        "5.1_换乘站最大日换乘量",
        "5.2_换乘能力匹配",
    ]
    missing = [name for name in required if not isinstance(parsed_data.get(name), dict)]
    if missing:
        raise ValueError(f"缺少分章数据对象：{'、'.join(missing)}")

    def find_forbidden_keys(value, path="data"):
        hits = []
        if isinstance(value, dict):
            for key, item in value.items():
                current = f"{path}.{key}"
                if "摘要" in str(key) or key == "重点活动显示说明":
                    hits.append(current)
                hits.extend(find_forbidden_keys(item, current))
        elif isinstance(value, list):
            for index, item in enumerate(value):
                hits.extend(find_forbidden_keys(item, f"{path}[{index}]"))
        return hits

    forbidden = find_forbidden_keys(parsed_data)
    if forbidden:
        raise ValueError(f"输入只允许筛选条件和事实数据，请移除页面摘要类字段：{'、'.join(forbidden[:8])}")

    chapter_1 = parsed_data["第1章_筛选条件及概况"]
    holiday_info = chapter_1.get("假期信息", {})
    holiday_name = str(holiday_info.get("名称") or "节假日").replace("（预测）", "").strip()
    report_title = str(chapter_1.get("报告标题") or f"{holiday_name}客流预测分析报告").strip()
    if not report_title:
        raise ValueError("报告标题不能为空")

    def markdown_value(value):
        if value is None:
            return "待业务系统提供"
        if isinstance(value, bool):
            return "是" if value else "否"
        if isinstance(value, list):
            return "、".join(str(item) for item in value) if value else "无"
        if isinstance(value, dict):
            return "；".join(f"{key}：{markdown_value(item)}" for key, item in value.items())
        return str(value)

    current_filter = chapter_1.get("页面当前筛选", {})
    if not isinstance(holiday_info, dict) or not isinstance(current_filter, dict):
        raise ValueError("第1章必须包含假期信息和页面当前筛选两个Object")

    info_lines = [
        f"- **预测节假日：** {markdown_value(current_filter.get('预测节假日'))}",
        f"- **假期日期：** {markdown_value(holiday_info.get('开始日期'))}至{markdown_value(holiday_info.get('结束日期'))}，共{markdown_value(holiday_info.get('放假天数'))}天",
        f"- **节前一天：** {markdown_value(holiday_info.get('节前一天'))}",
        f"- **对比日期范围：** {markdown_value(current_filter.get('对比开始日期'))}至{markdown_value(current_filter.get('对比结束日期'))}",
        f"- **异常日剔除：** 非节假日{markdown_value(current_filter.get('剔除非节假日异常日'))}；节假日{markdown_value(current_filter.get('剔除节假日异常日'))}",
        f"- **对比节假日：** {markdown_value([item.get('名称') for item in chapter_1.get('对比节假日', []) if isinstance(item, dict)])}",
        f"- **线路范围：** {markdown_value(chapter_1.get('线路范围', []))}",
    ]
    activity_rows = chapter_1.get("重点活动", [])
    activity_lines = []
    if isinstance(activity_rows, list) and activity_rows:
        for item in activity_rows:
            if isinstance(item, dict):
                activity_lines.append(f"- {markdown_value(item)}")
            else:
                activity_lines.append(f"- {markdown_value(item)}")
    else:
        activity_lines.append("- **重点活动数据：** 无")

    chapter_01_md = "\n".join([
        "### 1.1 假日信息与筛选",
        "",
        *info_lines,
        "",
        "### 1.2 假日重点活动",
        "",
        *activity_lines,
    ]).strip()

    sections = {
        "packet_021": ("2.1", "节前一天线路客运量", parsed_data.get("2.1_节前一天线路客运量")),
        "packet_022": ("2.2", "假日期间线路客运量", parsed_data.get("2.2_假日期间线路客运量")),
        "packet_031": ("3.1", "节前一天高峰断面", parsed_data.get("3.1_节前一天高峰断面")),
        "packet_032": ("3.2", "假日期间高峰断面", parsed_data.get("3.2_假日期间高峰断面")),
        "packet_0321": ("3.2.1", "分时断面与空间分布", parsed_data.get("3.2.1_分时断面与空间分布")),
        "packet_041": ("4.1", "重点车站预测客流", parsed_data.get("4.1_重点车站预测客流")),
        "packet_051": ("5.1", "换乘站最大日换乘量", parsed_data.get("5.1_换乘站最大日换乘量")),
        "packet_052": ("5.2", "换乘能力匹配", parsed_data.get("5.2_换乘能力匹配")),
    }

    packets = {}
    for output_name, (number, title, section_data) in sections.items():
        if not isinstance(section_data, dict) or not section_data:
            raise ValueError(f"缺少或清空小节数据：{number}_{title}")
        packet = {
            "报告标题": report_title,
            "章节序号": number,
            "章节标题": title,
            "章节数据": section_data,
        }
        text = json.dumps(packet, ensure_ascii=False, separators=(",", ":"))
        if len(text) > 30000:
            raise ValueError(f"{number}_{title}数据包超过30000字符，请由前端仅传当前显示结果")
        packets[output_name] = text

    return {
        "report_title": report_title,
        "chapter_01_md": chapter_01_md,
        "packet_021": packets["packet_021"],
        "packet_022": packets["packet_022"],
        "packet_031": packets["packet_031"],
        "packet_032": packets["packet_032"],
        "packet_0321": packets["packet_0321"],
        "packet_041": packets["packet_041"],
        "packet_051": packets["packet_051"],
        "packet_052": packets["packet_052"],
    }
